mapper.select:
SELECT r.id, r.post_id AS postId, r.user_id AS userId, r.parent_id AS parentId, r.reply_to_user_id AS replyToUserId, r.content, r.like_count AS likeCount, r.create_time AS createTime, p.title AS postTitle, u.username AS userName, u.avatar AS userAvatar, ru.username AS replyToUserName FROM post_reply r LEFT JOIN forum_post p ON r.post_id = p.id LEFT JOIN user_info u ON r.user_id = u.id LEFT JOIN user_info ru ON r.reply_to_user_id = ru.id WHERE r.is_deleted = 0
AND r.post_id = #{query.postId}
AND r.user_id = #{query.userId}
AND r.content LIKE CONCAT('%', #{query.keyword}, '%')
AND r.create_time >= #{query.startTime}
AND r.create_time <= #{query.endTime}
ORDER BY r.create_time DESC

